#include <iostream>


int main() {
    int value{}, delta{};
    if (!(std::cin >> value >> delta)) return 1;
    auto copy = value;
    auto& alias = value;
    alias += delta;
    ++copy;
    std::cout << value << ' ' << copy << ' ' << alias << '\n';
}
